package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.talents.*;
import com.customrpg.utils.*;
import com.customrpg.vfx.*;
import com.customrpg.vfx.VfxMath.V;
import com.customrpg.managers.NecroRoster.Kind;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.event.world.EntitiesLoadEvent;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.util.Vector;
import java.util.*;

/** One bounded combat clock for real minions, jobs, controls and shields. VFX never decides combat. */
public final class NecroTalentSkills implements Listener {
    private static final NamespacedKey SLOW=new NamespacedKey("customrpg","necro_slow"),ABSORB=new NamespacedKey("customrpg","necro_absorption");
    interface Motion {void set(LivingEntity e,double slow);void clear(LivingEntity e);}
    interface Transfer {void damage(LivingEntity target,double amount,LivingEntity attacker);}
    interface Body {Skeleton spawn(Player owner,Location at,Kind kind);}
    private final CustomRPG plugin;private final ExpandedTalentSkills combat;private final Motion motion;private final Body body;private final Transfer transfer;private final EarthShields shields;
    private BukkitTask task;private long tick;
    private record Cast(Player source,Talent talent,int rank,Location origin,Vector facing){}
    private record Job(Cast cast,long at,Runnable action){}
    private record Debuff(Cast cast,LivingEntity target,double amount,long starts,long until,boolean root){}
    private record Focus(LivingEntity target,long until){}
    private static final class Unit {
        final Cast cast;final Skeleton entity;final Kind kind;final long until;final NecroRoster.Attack attacks;final NecroVfx.Anchor anchor=new NecroVfx.Anchor();final Location origin;final Vector facing;
        boolean consumed,guardUsed;UUID visual;LivingEntity target;
        Unit(Cast c,Skeleton e,Kind k,long spawned){cast=c;entity=e;kind=k;until=spawned+k.duration;attacks=new NecroRoster.Attack(spawned);origin=e.getLocation().clone();facing=c.facing.clone();}
    }
    private record Follow(Cast cast,LivingEntity target,Location origin,Vector direction,NecroVfx.Anchor anchor,long until,UUID visual){}
    private static final class Gate {final Cast cast;final NecroVfx.Anchor anchor=new NecroVfx.Anchor();final long locks;Location origin;Vector direction;final Set<UUID> hits=new HashSet<>();Gate(Cast c,long now){cast=c;locks=now+30;}}
    private record Taunt(Cast cast,Mob mob,LivingEntity previous,Skeleton guard,long until){}
    private final Map<UUID,Unit> units=new LinkedHashMap<>();private final Map<UUID,Focus> focus=new HashMap<>();private final Map<UUID,Long> lanterns=new HashMap<>();
    private final List<Job> jobs=new ArrayList<>();private final List<Debuff> debuffs=new ArrayList<>();private final List<Follow> following=new ArrayList<>();private final List<Gate> gates=new ArrayList<>();private final List<Taunt> taunts=new ArrayList<>();
    private final Map<UUID,LivingEntity> slowed=new HashMap<>();private final Map<UUID,Double> applied=new HashMap<>();private final Map<UUID,Set<UUID>> visuals=new HashMap<>();
    public NecroTalentSkills(CustomRPG p,ExpandedTalentSkills combat){this(p,combat,null,null,null);}
    NecroTalentSkills(CustomRPG p,ExpandedTalentSkills combat,Motion movement,Body bodies,EarthShields.Access absorption){
        this(p,combat,movement,bodies,absorption,SkillDamageGuard::transfer);
    }
    NecroTalentSkills(CustomRPG p,ExpandedTalentSkills combat,Motion movement,Body bodies,EarthShields.Access absorption,Transfer transfer){
        plugin=p;this.combat=combat;this.transfer=transfer;
        motion=movement!=null?movement:new Motion(){public void clear(LivingEntity e){var a=e.getAttribute(Attribute.MOVEMENT_SPEED);if(a!=null)for(var m:new ArrayList<>(a.getModifiers()))if(m.getKey().equals(SLOW))a.removeModifier(m);}public void set(LivingEntity e,double n){clear(e);var a=e.getAttribute(Attribute.MOVEMENT_SPEED);if(a!=null&&n>0)a.addTransientModifier(new AttributeModifier(SLOW,-n,AttributeModifier.Operation.MULTIPLY_SCALAR_1));}};
        body=bodies!=null?bodies:(owner,at,kind)->at.getWorld().spawn(at,Skeleton.class,CreatureSpawnEvent.SpawnReason.CUSTOM,e->{
            ControlledUndead.mark(e,owner.getUniqueId());e.setAI(false);e.setPersistent(false);e.setRemoveWhenFarAway(false);e.setCanPickupItems(false);e.setSilent(true);e.setShouldBurnInDay(false);
            e.getAttribute(Attribute.MAX_HEALTH).setBaseValue(kind.hp);e.setHealth(kind.hp);e.getEquipment().clear();e.getEquipment().setItemInMainHand(new org.bukkit.inventory.ItemStack(kind==Kind.COLOSSUS?Material.IRON_AXE:Material.STONE_SWORD));e.getEquipment().setItemInMainHandDropChance(0);
            if(kind==Kind.COLOSSUS){e.getEquipment().setItemInOffHand(new org.bukkit.inventory.ItemStack(Material.SHIELD));e.getEquipment().setItemInOffHandDropChance(0);}
            if(kind==Kind.KNIGHT){e.getEquipment().setHelmet(new org.bukkit.inventory.ItemStack(Material.CHAINMAIL_HELMET));e.getEquipment().setChestplate(new org.bukkit.inventory.ItemStack(Material.CHAINMAIL_CHESTPLATE));e.getEquipment().setHelmetDropChance(0);e.getEquipment().setChestplateDropChance(0);}e.setCustomName("§7"+owner.getName()+" §f"+(kind==Kind.COLOSSUS?"葬骨巨衛":kind==Kind.KNIGHT?"精銳骸騎":"骸骨戰士"));e.setCustomNameVisible(true);
        });
        shields=new EarthShields(absorption!=null?absorption:new EarthShields.Access(){public double amount(Player p){return p.getAbsorptionAmount();}public void amount(Player p,double n){p.setAbsorptionAmount(n);}public void capacity(Player p,double own){var a=p.getAttribute(Attribute.MAX_ABSORPTION);if(a!=null){for(var m:new ArrayList<>(a.getModifiers()))if(m.getKey().equals(ABSORB))a.removeModifier(m);if(own>0)a.addTransientModifier(new AttributeModifier(ABSORB,own,AttributeModifier.Operation.ADD_NUMBER));}}});
    }
    public static void validate(Talent t){var s=NecroSkill.of(t.getId());if(s==null||t.getBranch()!=TalentBranch.NECROMANCER||t.getType()!=TalentType.ACTIVE||t.getMaxLevel()!=(s==NecroSkill.GATE?1:3)||t.getPointsPerLevel()!=1||t.getGuiSlot()!=s.slot||t.getManaCost()!=s.mana||t.getCooldown()!=s.cooldown||t.getHpCost()!=0)throw new IllegalArgumentException("Invalid Necromancer layout/cost");for(int n=1;n<=t.getMaxLevel();n++){var d=t.getLevelData(n);double damage=t.getEffectDouble(n,"baseDamage",-1);if(d==null||!d.scaling.isEmpty()||!d.effects.keySet().equals(Set.of("baseDamage","range"))||!Double.isFinite(damage)||damage<0||damage>32||t.getEffectDouble(n,"range",-1)!=s.range)throw new IllegalArgumentException("Invalid Necromancer effects");}}
    public void start(){if(task!=null)return;for(var w:plugin.getServer().getWorlds())for(var e:w.getEntities())if(ControlledUndead.is(e))e.remove();task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,1,1);}
    private static Vector flat(Player p){var d=p.getLocation().getDirection().setY(0);return d.lengthSquared()<.001?new Vector(0,0,1):d.normalize();}
    private V v(Location p){return new V(p.getX(),p.getY(),p.getZ());}
    private V local(Location origin,Vector direction,Location point){var f=VfxMath.Frame.facing(v(origin),new V(direction.getX(),direction.getY(),direction.getZ()),0);var delta=v(point).sub(v(origin));return new V(delta.dot(f.right()),delta.dot(f.up()),delta.dot(f.forward()));}
    private boolean valid(Cast c){var p=c.source;if(!p.isOnline()||p.isDead()||p.getGameMode()==GameMode.SPECTATOR||!p.getWorld().equals(c.origin.getWorld())||combat.protectedAt(p.getLocation()))return false;var pt=plugin.getTalentManager().getPlayerTalents(p);return pt.getTalentLevel(c.talent.getId())>0&&(NecroSkill.ultimate(c.talent.getId())?c.talent.getId().equals(pt.getUltimateSkill()):Arrays.asList(pt.getSelectedSkills()).contains(c.talent.getId()));}
    private boolean live(Unit u){return !u.consumed&&u.entity.isValid()&&!u.entity.isDead()&&tick<=u.until&&valid(u.cast)&&u.entity.getWorld().equals(u.cast.source.getWorld())&&!combat.protectedAt(u.entity.getLocation())&&u.entity.getLocation().distanceSquared(u.cast.source.getLocation())<=144;}
    private List<Unit> own(Player p){return units.values().stream().filter(u->u.cast.source.equals(p)&&live(u)).toList();}
    private boolean loaded(Location from,Vector dir,double distance){if(dir.lengthSquared()<.0001)return true;dir=dir.clone().normalize();for(double d=0;d<=distance+.4;d+=.4){var at=from.clone().add(dir.clone().multiply(Math.min(d,distance)));if(!at.getWorld().isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4))return false;}return true;}
    private boolean clear(Location from,Location to){if(!from.getWorld().equals(to.getWorld()))return false;var delta=to.toVector().subtract(from.toVector());double d=delta.length();return d<.1||loaded(from,delta,d)&&from.getWorld().rayTraceBlocks(from,delta.normalize(),Math.max(0,d-.05),FluidCollisionMode.NEVER,true)==null;}
    private Location ground(Location at){var w=at.getWorld();if(!w.isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4)||!w.getWorldBorder().isInside(at)||combat.protectedAt(at))return null;for(int y=at.getBlockY()+1;y>=at.getBlockY()-2;y--){if(y<w.getMinHeight()||y+3>=w.getMaxHeight())continue;var floor=w.getBlockAt(at.getBlockX(),y,at.getBlockZ());if(!floor.isPassable()&&!floor.isLiquid()&&w.getBlockAt(at.getBlockX(),y+1,at.getBlockZ()).isPassable()&&!w.getBlockAt(at.getBlockX(),y+1,at.getBlockZ()).isLiquid()&&w.getBlockAt(at.getBlockX(),y+2,at.getBlockZ()).isPassable())return new Location(w,at.getX(),floor.getBoundingBox().getMaxY()+.03,at.getZ(),at.getYaw(),0);}return null;}
    private List<Location> positions(Player p){var right=new Vector(flat(p).getZ(),0,-flat(p).getX());var result=new ArrayList<Location>();for(int side:new int[]{-1,1}){Location at=ground(p.getLocation().add(right.clone().multiply(side*1.2)).add(flat(p).multiply(.4)));if(at==null||!clear(p.getEyeLocation(),at.clone().add(0,1,0)))return List.of();result.add(at);}return result;}
    private LivingEntity aim(Player p,int range){return loaded(p.getEyeLocation(),p.getEyeLocation().getDirection(),range)?combat.aim(p,range):null;}
    private boolean fail(Player p,String why){p.sendMessage("§c"+why+"；未消耗魔力與冷卻。");return false;}
    private UUID show(Cast c,Location at,Vector direction,VfxRuntime.Effect effect,LivingEntity target){var fx=plugin.getVfxService();if(fx==null)return null;var id=fx.necro(c.source,c.talent.getId(),at,direction,effect,VfxRuntime.Mode.COMBAT,target,0);if(id!=null)visuals.computeIfAbsent(c.source.getUniqueId(),x->new HashSet<>()).add(id);return id;}
    private void stop(UUID id){if(id!=null&&plugin.getVfxService()!=null)plugin.getVfxService().runtime().cancelInstance(id);}
    private void follow(Cast c,LivingEntity target,NecroVfx.Anchor a,VfxRuntime.Effect effect,int duration){Location origin=target.getLocation().clone();UUID id=show(c,origin,c.facing,effect,target);if(id!=null)following.add(new Follow(c,target,origin,c.facing,a,tick+duration,id));}
    private void later(Cast c,int delay,Runnable r){jobs.add(new Job(c,tick+delay,r));}
    private boolean hit(Cast c,LivingEntity target,double damage,boolean followUp){if(!valid(c)||!combat.enemy(c.source,target)||damage<=0)return false;double before=MobManager.getVirtualCurrentHP(target)+target.getAbsorptionAmount();if(followUp)SkillDamageGuard.damageFollowUp(target,damage,c.source,false);else SkillDamageGuard.damage(target,damage,c.source);return MobManager.getVirtualCurrentHP(target)+target.getAbsorptionAmount()<before;}
    private boolean boss(LivingEntity target){if(target instanceof Wither||target instanceof EnderDragon||target instanceof Warden)return true;var m=plugin.getMobManager();var d=m==null?null:m.getMobData(m.getCustomMobKey(target));return d!=null&&d.isBoss();}
    private boolean permit(Cast c,LivingEntity e,NecroControlEvent.Kind kind,double amount,int duration){var event=new NecroControlEvent(c.source,e,kind,amount,duration);plugin.getServer().getPluginManager().callEvent(event);return !event.isCancelled();}
    private void control(Cast c,LivingEntity target,double n,int delay,int duration,boolean root){if(debuffs.size()>=2048||!permit(c,target,root?NecroControlEvent.Kind.ROOT:NecroControlEvent.Kind.SLOW,n,duration))return;debuffs.add(new Debuff(c,target,n,tick+delay,tick+delay+duration,root));}
    public boolean cleanseOrdinarySlow(LivingEntity target){var d=debuffs.stream().filter(e->e.target.equals(target)&&!e.root&&e.amount<1&&tick>=e.starts&&tick<e.until).findFirst().orElse(null);if(d==null)return false;debuffs.remove(d);applyControls();return true;}
    private void applyControls(){var values=new HashMap<UUID,Double>();for(var d:debuffs)if(tick>=d.starts){slowed.put(d.target.getUniqueId(),d.target);values.merge(d.target.getUniqueId(),d.amount,Math::max);}for(var id:new ArrayList<>(slowed.keySet())){double n=values.getOrDefault(id,0.0);if(n!=applied.getOrDefault(id,-1.0)){motion.set(slowed.get(id),n);applied.put(id,n);}if(n==0){slowed.remove(id);applied.remove(id);}}}
    private void remove(Unit u,boolean fragments){if(u.consumed)return;u.consumed=true;units.remove(u.entity.getUniqueId());stop(u.visual);if(fragments&&valid(u.cast))show(u.cast,u.entity.getLocation(),u.facing,new NecroVfx.Fragments(),null);u.entity.remove();}
    /** Prepare both bodies before replacing a live roster; a cancelled spawn cannot consume the old squad. */
    private boolean replace(Cast c,List<Location> at,Kind kind){int count=kind==Kind.COLOSSUS?1:2;if(at.size()<count||units.size()+count>128)return false;List<Skeleton> prepared=new ArrayList<>();try{for(int i=0;i<count;i++){Skeleton e=body.spawn(c.source,at.get(i),kind);if(e==null||!e.isValid()||e.isDead()){if(e!=null)e.remove();throw new IllegalStateException("Summon spawn rejected");}prepared.add(e);}}catch(RuntimeException rejected){prepared.forEach(Entity::remove);return false;}
        for(var old:new ArrayList<>(units.values()))if(old.cast.source.equals(c.source))remove(old,false);
        for(var e:prepared){var u=new Unit(c,e,kind,tick);units.put(e.getUniqueId(),u);u.visual=show(c,u.origin,u.facing,new NecroVfx.Companion(u.anchor,kind.duration+1,kind==Kind.COLOSSUS),e);}
        return true;
    }
    public boolean cast(Player p,Talent talent,int rank){var s=NecroSkill.of(talent.getId());if(s==null)return false;var c=new Cast(p,talent,rank,p.getLocation().clone(),flat(p));if(!valid(c)||jobs.size()>=192)return false;double d=talent.getEffectDouble(rank,"baseDamage",s.damage);
        switch(s){
            case LANCE->{Location eye=p.getEyeLocation().clone();Vector dir=eye.getDirection();if(!loaded(eye,dir,14))return fail(p,"前方區塊尚未載入");var wall=p.getWorld().rayTraceBlocks(eye,dir,14,FluidCollisionMode.NEVER,true);double reach=wall==null?14:Math.max(0,wall.getHitPosition().distance(eye.toVector())-.05);show(c,eye,dir,new NecroVfx.Lance(reach),null);var seen=new HashSet<UUID>();boolean[] stopped={false};
                for(int step=0;step<7;step++){int segment=step;later(c,6+step,()->{if(stopped[0]||seen.size()>=2)return;Location from=eye.clone().add(dir.clone().multiply(segment*2));double length=Math.min(2,reach-segment*2);if(length<=0){stopped[0]=true;return;}var block=p.getWorld().rayTraceBlocks(from,dir,length,FluidCollisionMode.NEVER,true);if(block!=null){length=Math.max(0,block.getHitPosition().distance(from.toVector())-.05);stopped[0]=true;}if(length<=0)return;
                    while(seen.size()<2){var ray=p.getWorld().rayTraceEntities(from,dir,length,.3,e->e instanceof LivingEntity t&&!seen.contains(t.getUniqueId())&&combat.enemy(p,t));if(ray==null||!(ray.getHitEntity() instanceof LivingEntity target))break;double amount=seen.isEmpty()?d:d*5/8;seen.add(target.getUniqueId());if(hit(c,target,amount,false))show(c,target.getLocation(),dir,new NecroVfx.Fragments(),null);}
                });}}
            case SUMMON->{if(own(p).stream().anyMatch(u->u.kind==Kind.COLOSSUS))return fail(p,"葬骨巨衛佔用兩個召喚欄位");var at=positions(p);if(at.size()!=2||!replace(c,at,Kind.WARRIOR))return fail(p,"需要左右兩處安全召喚位置且生成必須獲准");show(c,c.origin,c.facing,new NecroVfx.Summoning(),null);}
            case COMMAND->{LivingEntity target=aim(p,12);if(target==null)return fail(p,"請瞄準12格內可見敵人");hit(c,target,d,false);focus.put(p.getUniqueId(),new Focus(target,tick+120));for(var u:own(p))u.attacks.command();var a=new NecroVfx.Anchor();a.end=local(c.origin,c.facing,target.getEyeLocation());show(c,c.origin,c.facing,new NecroVfx.Command(a),target);}
            case PRISON->{LivingEntity target=aim(p,10);if(target==null)return fail(p,"請瞄準10格內可見敵人");if(hit(c,target,d,false)){if(!boss(target)){control(c,target,1,0,24,true);control(c,target,.25,24,40,false);}else control(c,target,.25,0,40,false);show(c,target.getLocation(),c.facing,new NecroVfx.Prison(),target);}}
            case LANTERN->{lanterns.put(p.getUniqueId(),tick+100);shields.grant(p,p.getUniqueId(),s.id,5,tick+100);var a=new NecroVfx.Anchor();follow(c,p,a,new NecroVfx.Lantern(a,false),110);}
            case SACRIFICE->{var chosen=own(p).stream().filter(u->u.kind==Kind.WARRIOR&&u.entity.getLocation().distanceSquared(p.getLocation())<=100&&p.hasLineOfSight(u.entity)).min(Comparator.comparingDouble(u->aimDistance(p,u.entity.getEyeLocation()))).orElse(null);if(chosen==null)return fail(p,"10格內沒有可獻祭的普通骸骨戰士");Location center=chosen.entity.getLocation().clone();remove(chosen,false);show(c,center,c.facing,new NecroVfx.Sacrifice(p.getUniqueId().getLeastSignificantBits()^tick),null);later(c,11,()->{for(var target:combat.enemies(p,center,3))if(hit(c,target,d,false))control(c,target,.25,0,40,false);});}
            case COLOSSUS->{var normal=own(p).stream().filter(u->u.kind==Kind.WARRIOR).toList();if(normal.size()<2)return fail(p,"需要兩名存活的普通骸骨戰士");Location center=ground(normal.get(0).entity.getLocation().clone().add(normal.get(1).entity.getLocation()).multiply(.5));if(center==null||!clear(p.getEyeLocation(),center.clone().add(0,1,0))||!replace(c,List.of(center),Kind.COLOSSUS))return fail(p,"融合位置不安全或實體生成遭拒");show(c,center,c.facing,new NecroVfx.Fusion(),null);Unit giant=own(p).get(0);for(var target:combat.enemies(p,center,4))if(target instanceof Mob mob&&!boss(target)&&permit(c,target,NecroControlEvent.Kind.TAUNT,0,40)){var previous=mob.getTarget();mob.setTarget(giant.entity);if(mob.getTarget()==giant.entity)taunts.add(new Taunt(c,mob,previous,giant.entity,tick+40));}}
            case GATE->{if(gates.size()>=64)return fail(p,"目前同時施法數量已達上限");var gate=new Gate(c,tick);gates.add(gate);gate.anchor.direction=new V(c.facing.getX(),0,c.facing.getZ());show(c,c.origin,c.facing,new NecroVfx.Gate(gate.anchor),null);control(c,p,.35,0,30,false);later(c,30,()->{gate.origin=p.getLocation().clone();gate.direction=flat(p);gate.anchor.offset=v(gate.origin).sub(v(c.origin));gate.anchor.direction=new V(gate.direction.getX(),0,gate.direction.getZ());});for(int wave=0;wave<3;wave++){int stage=wave;later(c,43+wave*10,()->wave(gate,stage,d));}later(c,71,()->{var at=positions(p);if(at.size()==2)replace(c,at,Kind.KNIGHT);gates.remove(gate);});}
        }
        applyControls();return true;
    }
    private double aimDistance(Player p,Location target){var delta=target.toVector().subtract(p.getEyeLocation().toVector());return delta.lengthSquared()<.01?0:1-delta.normalize().dot(p.getEyeLocation().getDirection());}
    private void wave(Gate gate,int wave,double base){if(gate.origin==null)return;var p=gate.cast.source;var center=gate.origin.clone().add(gate.direction.clone().multiply(7));var seen=new HashSet<UUID>();for(var e:p.getWorld().getNearbyEntities(center,10,4,10)){if(!(e instanceof LivingEntity t)||!combat.enemy(p,t)||!seen.add(t.getUniqueId()))continue;V q=local(gate.origin,gate.direction,t.getLocation());if(Math.abs(q.x())>4.5||q.z()<0||q.z()>14||Math.abs(q.y())>3)continue;Location lane=gate.origin.clone().add(new Vector(gate.direction.getZ(),0,-gate.direction.getX()).multiply(q.x())).add(0,1,0);if(!clear(gate.origin.clone().add(0,1,0),lane)||!clear(lane,t.getEyeLocation()))continue;if(hit(gate.cast,t,wave==2?base*1.5:base,gate.hits.contains(t.getUniqueId()))){gate.hits.add(t.getUniqueId());if(wave==1)control(gate.cast,t,.2,0,40,false);}}}
    private void moveUnit(Unit u,Location destination,double speed){Location start=u.entity.getLocation();var delta=destination.toVector().subtract(start.toVector()).setY(0);double distance=delta.length();if(distance<.5)return;Location sample=start.clone().add(delta.normalize().multiply(Math.min(speed,distance-.4)));Location at=ground(sample);if(at==null||Math.abs(at.getY()-start.getY())>1.05||!clear(start.clone().add(0,.8,0),at.clone().add(0,.8,0))||u.entity.collidesAt(at))return;at.setDirection(destination.toVector().subtract(at.toVector()).setY(0));u.entity.teleport(at);}
    private void update(Unit u){
        var p=u.cast.source;var command=focus.get(p.getUniqueId());LivingEntity target=command!=null&&tick<command.until&&combat.enemy(p,command.target)&&command.target.getLocation().distanceSquared(p.getLocation())<=144?command.target:null;
        if(target==null){if(tick%10==0||u.target==null||!combat.enemy(p,u.target))u.target=combat.enemies(p,u.entity.getLocation(),6).stream().min(Comparator.comparingDouble(t->t.getLocation().distanceSquared(u.entity.getLocation()))).orElse(null);target=u.target!=null&&combat.enemy(p,u.target)&&u.target.getLocation().distanceSquared(p.getLocation())<=144?u.target:null;}
        if(target==null){Location home=p.getLocation().add(new Vector(u.facing.getZ(),0,-u.facing.getX()).multiply(u.entity.getUniqueId().getLeastSignificantBits()%2==0?1.2:-1.2));if(tick%2==0)moveUnit(u,home,.25);}else{double distance=u.entity.getLocation().distanceSquared(target.getLocation());if(distance<=4&&clear(u.entity.getEyeLocation(),target.getEyeLocation())&&u.attacks.ready(u.kind,tick)){int amount=u.attacks.commit(u.kind,tick);if(hit(u.cast,target,amount,true)){u.anchor.pulse=7;u.entity.swingMainHand();}}else if(tick%2==0)moveUnit(u,target.getLocation(),.25*(command!=null&&tick<command.until?1.2:1));}
        u.anchor.offset=v(u.entity.getLocation()).sub(v(u.origin));if(u.anchor.pulse>0)u.anchor.pulse--;
    }
    void tick(){tick++;for(var u:new ArrayList<>(units.values())){if(!live(u))remove(u,true);else update(u);}for(var job:new ArrayList<>(jobs))if(job.at<=tick){jobs.remove(job);if(valid(job.cast))job.action.run();}else if(!valid(job.cast))jobs.remove(job);
        debuffs.removeIf(d->tick>=d.until||!d.target.isValid()||d.target.isDead()||!valid(d.cast)||!d.target.getWorld().equals(d.cast.origin.getWorld())||combat.protectedAt(d.target.getLocation()));applyControls();
        gates.removeIf(g->!valid(g.cast));for(var g:gates)if(tick<g.locks){g.anchor.offset=v(g.cast.source.getLocation()).sub(v(g.cast.origin));var f=flat(g.cast.source);g.anchor.direction=new V(f.getX(),0,f.getZ());}
        for(var f:new ArrayList<>(following)){if(tick>=f.until||!valid(f.cast)||!f.target.isValid()||f.target.isDead()){following.remove(f);stop(f.visual);continue;}f.anchor.offset=v(f.target.getLocation()).sub(v(f.origin));f.anchor.companions=own(f.cast.source).stream().map(u->local(f.target.getLocation(),f.direction,u.entity.getLocation())).toList();if(f.anchor.pulse>0)f.anchor.pulse--;}
        for(var t:new ArrayList<>(taunts))if(tick>=t.until||!valid(t.cast)||!t.guard.isValid()){restore(t);taunts.remove(t);}focus.entrySet().removeIf(e->tick>=e.getValue().until||!e.getValue().target.isValid());lanterns.values().removeIf(t->tick>=t);shields.tick(tick);
        if(tick%20==0&&plugin.getVfxService()!=null){var runtime=plugin.getVfxService().runtime();visuals.values().forEach(ids->ids.removeIf(id->!runtime.active(id)));visuals.values().removeIf(Set::isEmpty);}
    }
    private void restore(Taunt t){if(t.mob.isValid()&&t.mob.getTarget()==t.guard)t.mob.setTarget(t.previous!=null&&t.previous.isValid()&&!t.previous.isDead()?t.previous:null);}
    private LivingEntity attacker(EntityDamageEvent e){if(!(e instanceof EntityDamageByEntityEvent b))return null;return b.getDamager() instanceof LivingEntity l?l:b.getDamager() instanceof Projectile shot&&shot.getShooter() instanceof LivingEntity l?l:null;}
    /** Invoked by the final balance listener. Transfer loss is measured, never granted if rejected. */
    public void mitigate(EntityDamageEvent e){if(e.isCancelled()||SkillDamageGuard.isTransfer(e.getEntity()))return;Unit unit=units.get(e.getEntity().getUniqueId());if(unit!=null&&lanterns.getOrDefault(unit.cast.source.getUniqueId(),0L)>tick)e.setDamage(e.getDamage()*.6);
        if(!(e.getEntity() instanceof Player p)||SkillDamageGuard.isPeriodic(attacker(e)))return;var enemy=attacker(e);if(enemy==null||!combat.enemy(p,enemy)||e.getFinalDamage()<=0)return;Unit giant=own(p).stream().filter(u->u.kind==Kind.COLOSSUS&&!u.guardUsed&&u.entity.getLocation().distanceSquared(p.getLocation())<=16).findFirst().orElse(null);if(giant==null)return;giant.guardUsed=true;double amount=Math.min(6,e.getFinalDamage()),before=giant.entity.getHealth()+giant.entity.getAbsorptionAmount();transfer.damage(giant.entity,amount,enemy);double lost=Math.clamp(before-giant.entity.getHealth()-giant.entity.getAbsorptionAmount(),0,amount);if(lost<=0){giant.guardUsed=false;return;}double raw=e.getDamage(),finalDamage=e.getFinalDamage();if(finalDamage>0)e.setDamage(raw*Math.max(0,finalDamage-lost)/finalDamage);giant.anchor.pulse=9;}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true)public void friendly(EntityDamageEvent e){if(e instanceof EntityDamageByEntityEvent b&&ControlledUndead.is(b.getDamager())){e.setCancelled(true);return;}var u=units.get(e.getEntity().getUniqueId());if(u==null)return;var attacker=attacker(e);if(SkillDamageGuard.isTransfer(e.getEntity()))return;if(attacker==null||!combat.enemy(u.cast.source,attacker)||attacker.hasMetadata("beast_owner")){e.setCancelled(true);}}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void injured(EntityDamageEvent e){var u=units.get(e.getEntity().getUniqueId());if(u!=null&&e.getFinalDamage()>0)for(var f:following)if(f.cast.source.equals(u.cast.source))f.anchor.pulse=6;}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void target(EntityTargetLivingEntityEvent e){for(int i=taunts.size()-1;i>=0;i--){var t=taunts.get(i);if(t.mob.equals(e.getEntity())&&tick<t.until&&valid(t.cast)&&t.guard.isValid()&&!t.guard.isDead()&&t.guard.getWorld().equals(t.mob.getWorld())){e.setTarget(t.guard);return;}}if(ControlledUndead.is(e.getEntity()))e.setCancelled(true);else if(ControlledUndead.is(e.getTarget())){var unit=units.get(e.getTarget().getUniqueId());if(unit==null||!(e.getEntity() instanceof LivingEntity l)||!combat.enemy(unit.cast.source,l)||e.getEntity().hasMetadata("beast_owner"))e.setCancelled(true);}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void transform(EntityTransformEvent e){if(ControlledUndead.is(e.getEntity()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void combust(EntityCombustEvent e){if(ControlledUndead.is(e.getEntity()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void portal(EntityPortalEvent e){if(ControlledUndead.is(e.getEntity()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void projectile(ProjectileLaunchEvent e){if(e.getEntity().getShooter() instanceof Entity source&&ControlledUndead.is(source))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST)public void death(EntityDeathEvent e){if(e.getEntity() instanceof Player p)cancel(p);if(ControlledUndead.is(e.getEntity())){e.getDrops().clear();e.setDroppedExp(0);var u=units.get(e.getEntity().getUniqueId());if(u!=null)remove(u,true);}}
    @EventHandler public void load(EntitiesLoadEvent e){for(var entity:e.getEntities())if(ControlledUndead.is(entity)&&!units.containsKey(entity.getUniqueId()))entity.remove();}
    private boolean rooted(LivingEntity e){return debuffs.stream().anyMatch(d->d.target.equals(e)&&d.root&&tick>=d.starts&&tick<d.until&&valid(d.cast));}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void move(PlayerMoveEvent e){if(e.getTo()!=null&&rooted(e.getPlayer())&&(e.getFrom().getX()!=e.getTo().getX()||e.getFrom().getZ()!=e.getTo().getZ())){var stop=e.getFrom().clone();stop.setYaw(e.getTo().getYaw());stop.setPitch(e.getTo().getPitch());e.setTo(stop);}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void mobMove(io.papermc.paper.event.entity.EntityMoveEvent e){if(rooted(e.getEntity())){var to=e.getTo().clone();to.setX(e.getFrom().getX());to.setZ(e.getFrom().getZ());e.setTo(to);}}
    public void cancel(Player p){for(var u:new ArrayList<>(units.values()))if(u.cast.source.equals(p))remove(u,false);jobs.removeIf(j->j.cast.source.equals(p));debuffs.removeIf(d->d.cast.source.equals(p));following.removeIf(f->{if(f.cast.source.equals(p)){stop(f.visual);return true;}return false;});gates.removeIf(g->g.cast.source.equals(p));for(var t:new ArrayList<>(taunts))if(t.cast.source.equals(p)){restore(t);taunts.remove(t);}focus.remove(p.getUniqueId());lanterns.remove(p.getUniqueId());shields.owner(p.getUniqueId());var ids=visuals.remove(p.getUniqueId());if(ids!=null)ids.forEach(this::stop);applyControls();}
    public void clear(){for(var u:new ArrayList<>(units.values()))remove(u,false);jobs.clear();debuffs.clear();following.forEach(f->stop(f.visual));following.clear();gates.clear();taunts.forEach(this::restore);taunts.clear();focus.clear();lanterns.clear();shields.clear();visuals.values().forEach(ids->ids.forEach(this::stop));visuals.clear();applyControls();}
    public void shutdown(){if(task!=null){task.cancel();task=null;}clear();}
    @EventHandler public void quit(PlayerQuitEvent e){cancel(e.getPlayer());}
    @EventHandler public void world(PlayerChangedWorldEvent e){cancel(e.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void teleport(PlayerTeleportEvent e){var skills=plugin.getTalentSkillManager();if(skills!=null&&(skills.getFrost()!=null&&skills.getFrost().internalStep(e.getPlayer())||skills.getEarth()!=null&&skills.getEarth().internalRush(e.getPlayer())||skills.getDark()!=null&&skills.getDark().internalStep(e.getPlayer())))return;cancel(e.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void mode(PlayerGameModeChangeEvent e){cancel(e.getPlayer());}
}
